CREATE TABLE `shop` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '谷店名称',
  `mall_id` bigint unsigned DEFAULT NULL COMMENT '所属商圈ID',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '所属用户ID',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '省',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市',
  `district` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区县',
  `address` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '详细地址',
  `mall_floor` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商圈楼层',
  `description` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `storefront_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺店面图片URL',
  `featured_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '镇店之宝图片URL',
  `inside_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店内图片URL',
  `longitude` decimal(10,7) NOT NULL COMMENT '经度',
  `latitude` decimal(10,7) NOT NULL COMMENT '纬度',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '运营状态: 0-正常, 1-倒闭, 2-删除, 3-疑似误标',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序排名，数值越大越靠前',
  `bilibili_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'B站ID',
  `douyin_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抖音ID',
  `xiaohongshu_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '小红书ID',
  `wechat_public_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信公众号ID',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_mall_id` (`mall_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_city_district` (`city`,`district`),
  KEY `idx_location` (`longitude`,`latitude`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_latitude` (`latitude`)
) ENGINE=InnoDB AUTO_INCREMENT=2968 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='谷店表';
